import React, { useEffect, useRef, useState } from 'react';
import { Box, Container, Typography, Grid, Chip, Button } from '@mui/material';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { devData } from '../data/portfolioData';

gsap.registerPlugin(ScrollTrigger);

const FlipCard = ({ project, index }) => {
  const [flipped, setFlipped] = useState(false);
  const cardRef = useRef();

  useEffect(() => {
    gsap.fromTo(cardRef.current,
      { y: 80, opacity: 0, scale: 0.9 },
      {
        y: 0, opacity: 1, scale: 1,
        duration: 0.7,
        delay: (index % 3) * 0.15,
        ease: 'power3.out',
        scrollTrigger: {
          trigger: cardRef.current,
          start: 'top 88%',
          once: true
        }
      }
    );
  }, [index]);

  return (
    <Box
      ref={cardRef}
      sx={{
        height: '320px',
        perspective: '1000px',
        cursor: 'pointer'
      }}
      onMouseEnter={() => setFlipped(true)}
      onMouseLeave={() => setFlipped(false)}
    >
      <Box sx={{
        position: 'relative',
        width: '100%',
        height: '100%',
        transformStyle: 'preserve-3d',
        transition: 'transform 0.7s cubic-bezier(0.4, 0, 0.2, 1)',
        transform: flipped ? 'rotateY(180deg)' : 'rotateY(0deg)'
      }}>
        {/* Front */}
        <Box sx={{
          position: 'absolute', inset: 0,
          backfaceVisibility: 'hidden',
          background: 'linear-gradient(145deg, #ffffff, #f8f9ff)',
          borderRadius: '20px',
          border: '1px solid rgba(102,126,234,0.12)',
          boxShadow: '0 8px 30px rgba(102,126,234,0.1)',
          display: 'flex',
          flexDirection: 'column',
          p: 4,
          overflow: 'hidden'
        }}>
          {/* Decorative circle */}
          <Box sx={{
            position: 'absolute', top: -30, right: -30,
            width: '120px', height: '120px', borderRadius: '50%',
            background: 'linear-gradient(135deg, rgba(102,126,234,0.08), rgba(118,75,162,0.06))'
          }} />

          <Typography sx={{ fontSize: '3rem', mb: 2 }}>{project.image}</Typography>

          <Typography sx={{
            fontFamily: '"Clash Display", sans-serif',
            fontSize: '1.3rem', fontWeight: 700,
            color: '#1a1a2e', mb: 1
          }}>
            {project.name}
          </Typography>

          <Typography sx={{
            fontSize: '0.88rem', color: '#6a6a8e', lineHeight: 1.7,
            fontFamily: '"DM Sans", sans-serif', flex: 1
          }}>
            {project.description.substring(0, 100)}...
          </Typography>

          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mt: 2 }}>
            {project.tech.slice(0, 3).map(t => (
              <Chip key={t} label={t} size="small" sx={{
                fontFamily: '"Space Mono", monospace', fontSize: '0.65rem',
                background: 'rgba(102,126,234,0.08)', color: '#667eea',
                border: '1px solid rgba(102,126,234,0.2)'
              }} />
            ))}
          </Box>

          <Typography sx={{
            mt: 2, fontSize: '0.72rem', color: '#b0b0d0',
            fontFamily: '"Space Mono", monospace', textAlign: 'center'
          }}>
            Hover to see more ✦
          </Typography>
        </Box>

        {/* Back */}
        <Box sx={{
          position: 'absolute', inset: 0,
          backfaceVisibility: 'hidden',
          transform: 'rotateY(180deg)',
          background: 'linear-gradient(135deg, #1a1a2e, #302b63)',
          borderRadius: '20px',
          display: 'flex',
          flexDirection: 'column',
          p: 4,
          justifyContent: 'space-between'
        }}>
          <Box>
            <Typography sx={{
              fontFamily: '"Clash Display", sans-serif',
              fontSize: '1.3rem', fontWeight: 700,
              color: 'white', mb: 2
            }}>
              {project.name}
            </Typography>
            <Typography sx={{
              fontSize: '0.88rem', color: 'rgba(255,255,255,0.7)',
              lineHeight: 1.7, fontFamily: '"DM Sans", sans-serif'
            }}>
              {project.description}
            </Typography>
          </Box>

          <Box>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mb: 3 }}>
              {project.tech.map(t => (
                <Chip key={t} label={t} size="small" sx={{
                  fontFamily: '"Space Mono", monospace', fontSize: '0.65rem',
                  background: 'rgba(102,126,234,0.2)', color: '#a0b4ff',
                  border: '1px solid rgba(102,126,234,0.3)'
                }} />
              ))}
            </Box>
            <Box sx={{ display: 'flex', gap: 1.5 }}>
              <Button
                href={project.github}
                size="small"
                variant="outlined"
                sx={{
                  color: 'white', borderColor: 'rgba(255,255,255,0.3)',
                  fontFamily: '"Space Mono", monospace', fontSize: '0.7rem',
                  textTransform: 'none', borderRadius: '20px', px: 2,
                  '&:hover': { borderColor: '#667eea', background: 'rgba(102,126,234,0.2)' }
                }}
              >
                GitHub →
              </Button>
              <Button
                href={project.live}
                size="small"
                variant="contained"
                sx={{
                  background: 'linear-gradient(135deg, #667eea, #764ba2)',
                  fontFamily: '"Space Mono", monospace', fontSize: '0.7rem',
                  textTransform: 'none', borderRadius: '20px', px: 2,
                  '&:hover': { background: 'linear-gradient(135deg, #5a72e0, #6a4296)' }
                }}
              >
                Live Demo
              </Button>
            </Box>
          </Box>
        </Box>
      </Box>
    </Box>
  );
};

const Projects = () => {
  const sectionRef = useRef();
  const headingRef = useRef();

  useEffect(() => {
    gsap.fromTo(headingRef.current,
      { y: 50, opacity: 0 },
      {
        y: 0, opacity: 1, duration: 0.8,
        scrollTrigger: { trigger: sectionRef.current, start: 'top 80%', once: true }
      }
    );
  }, []);

  return (
    <Box
      ref={sectionRef}
      id="projects"
      sx={{
        py: { xs: 10, md: 14 },
        background: 'linear-gradient(180deg, #ffffff 0%, #f0f2ff 100%)',
        position: 'relative',
        overflow: 'hidden'
      }}
    >
      {/* BG pattern */}
      <Box sx={{
        position: 'absolute', inset: 0, opacity: 0.03,
        backgroundImage: `radial-gradient(#667eea 1px, transparent 1px)`,
        backgroundSize: '30px 30px'
      }} />

      <Container maxWidth="lg">
        <Box ref={headingRef} sx={{ mb: 8, textAlign: 'center' }}>
          <Typography sx={{
            color: '#667eea', fontFamily: '"Space Mono", monospace',
            fontSize: '0.75rem', letterSpacing: '4px', mb: 2, textTransform: 'uppercase'
          }}>
            — My Work
          </Typography>
          <Typography variant="h2" sx={{
            fontWeight: 800, fontSize: { xs: '2.5rem', md: '3.5rem' },
            fontFamily: '"Clash Display", sans-serif',
            background: 'linear-gradient(135deg, #1a1a2e, #302b63)',
            WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text',
            mb: 2
          }}>
            Projects That Speak
          </Typography>
          <Typography sx={{ color: '#7a7aa0', fontFamily: '"DM Sans", sans-serif', fontSize: '1rem' }}>
            Hover over cards to explore — built with passion and purpose
          </Typography>
        </Box>

        <Grid container spacing={3}>
          {devData.projects.map((project, i) => (
            <Grid item xs={12} sm={6} md={4} key={project.name}>
              <FlipCard project={project} index={i} />
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
};

export default Projects;
